1	package security
2	
3	import (
4		"sort"
5		"strconv"
6		"strings"
7	
8		"charm.land/lipgloss/v2"
9	
10		"github.com/anthnel/devdesk/internal/remediation"
11		"github.com/anthnel/devdesk/internal/scan"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// DEVDESK-754 (SC1, step 2): the pure half of "Group by fix". Nothing here
17	// touches the Model; the toggle, the level and the rendering live elsewhere.
18	
19	// groupKey identifies a group across two scans: what it is about, never its
20	// members or its target, so a re-scan finds the same row again.
21	type groupKey struct {
22		Ecosystem, Subject, Installed string
23		Unfixed                       bool
24	}
25	
26	// fixGroup is one row of the grouped list.
27	type fixGroup struct {
28		Key      groupKey
29		Severity scan.SeverityLevel
30		// Subject is the package, or the ID of a vulnerability that names none.
31		Subject string
32		// Change is the delta shown in the table, "1.1.1k -> 1.1.1w".
33		Change string
34		// Target is the one version the group moves to, "" when the versions could
35		// not be ordered (several candidates) or none is published.
36		Target string
37		// Status is the Fix column, from fixStatusOf.
38		Status fixStatus
39		// Command is the group's command, "" when none is known or it is not plain
40		// words (scan.PlainWords).
41		Command string
42		// Members are every finding of the group, not only the visible ones.
43		Members []scan.Finding
44	}
45	
46	// cveGroups groups the vulnerabilities of findings by the cause that clears
47	// them, from remediation.GroupAll. Worst severity first, then the most
48	// findings, then Subject, then Change.
49	func cveGroups(findings []scan.Finding) []fixGroup {
50		fixes := remediation.GroupAll(findings)
51		groups := make([]fixGroup, 0, len(fixes))
52		for _, fx := range fixes {
53			if len(fx.Members) == 0 {
54				continue
55			}
56			g := fixGroup{
57				Key:      groupKey{Ecosystem: fx.Ecosystem, Subject: fx.Package, Installed: fx.Installed, Unfixed: fx.Unfixed},
58				Severity: fx.Severity,
59				Subject:  fx.Package,
60				Change:   fixChange(fx),
61				Target:   fx.Target,
62				Status:   fixStatusOf(fx.Members[0], false),
63				Members:  fx.Members,
64			}
65			if fx.Command != "" && scan.PlainWords(fx.Command) {
66				g.Command = fx.Command
67			}
68			groups = append(groups, g)
69		}
70		sort.SliceStable(groups, func(i, j int) bool {
71			a, b := groups[i], groups[j]
72			if ra, rb := severityRank(a.Severity), severityRank(b.Severity); ra != rb {
73				return ra > rb
74			}
75			if len(a.Members) != len(b.Members) {
76				return len(a.Members) > len(b.Members)
77			}
78			if a.Subject != b.Subject {
79				return a.Subject < b.Subject
80			}
81			return a.Change < b.Change
82		})
83		return groups
84	}
85	
86	// fixChange is the delta of a fix: the installed version, an arrow and what it
87	// moves to. An unfixed group moves to none; versions that could not be ordered
88	// are all listed, none preferred.
89	func fixChange(fx remediation.Fix) string {
90		installed := fx.Installed
91		if installed == "" {
92			installed = "unknown"
93		}
94		switch {
95		case fx.Unfixed:
96			return installed + " -> none"
97		case fx.Target != "":
98			return installed + " -> " + fx.Target
99		}
100		var options []string
101		for _, o := range fx.Options {
102			for _, v := range strings.Split(o, ",") {
103				if v = strings.TrimSpace(v); v != "" {
104					options = append(options, v)
105				}
106			}
107		}
108		if len(options) == 0 {
109			return installed + " -> none"
110		}
111		return installed + " -> " + strings.Join(options, " or ")
112	}
113	
114	// findingIdentity is what sameFinding compares, as a map key.
115	type findingIdentity struct {
116		source, rule, file, pkg, version, instance string
117	}
118	
119	func identityOf(f scan.Finding) findingIdentity {
120		return findingIdentity{f.Source, remediation.RuleKey(f.ID), f.File, f.PkgName, f.Version, instanceOf(f)}
121	}
122	
123	// visibleGroups keeps the groups with at least one member in visible (matched
124	// by sameFinding), in the order of all. A kept group keeps all its members.
125	func visibleGroups(all []fixGroup, visible []scan.Finding) []fixGroup {
126		shown := make(map[findingIdentity]struct{}, len(visible))
127		for _, f := range visible {
128			shown[identityOf(f)] = struct{}{}
129		}
130		kept := make([]fixGroup, 0, len(all))
131		for _, g := range all {
132			for _, f := range g.Members {
133				if _, ok := shown[identityOf(f)]; ok {
134					kept = append(kept, g)
135					break
136				}
137			}
138		}
139		return kept
140	}
141	
142	// groupIndexOf is the index of the group that holds f, -1 if none.
143	func groupIndexOf(groups []fixGroup, f scan.Finding) int {
144		for i, g := range groups {
145			for _, member := range g.Members {
146				if sameFinding(member, f) {
147					return i
148				}
149			}
150		}
151		return -1
152	}
153	
154	// groupIndexByKey is the index of the group with key, else prev clamped into
155	// the list, -1 for an empty list.
156	func groupIndexByKey(groups []fixGroup, key groupKey, prev int) int {
157		for i, g := range groups {
158			if g.Key == key {
159				return i
160			}
161		}
162		return clampIndex(prev, len(groups))
163	}
164	
165	// clampIndex puts i into [0, n), -1 when n is 0.
166	func clampIndex(i, n int) int {
167		if n == 0 {
168			return -1
169		}
170		return max(0, min(i, n-1))
171	}
172	
173	// nearestFinding is the index in visible the findings cursor goes to when the
174	// grouped list is left (AC4): the first visible member of g, else prev if it is
175	// still visible, else prevCursor clamped into the list, -1 if visible is empty.
176	func nearestFinding(visible []scan.Finding, g *fixGroup, prev *scan.Finding, prevCursor int) int {
177		if len(visible) == 0 {
178			return -1
179		}
180		if g != nil && len(g.Members) > 0 {
181			for i, f := range visible {
182				for _, member := range g.Members {
183					if sameFinding(member, f) {
184						return i
185					}
186				}
187			}
188		}
189		if prev != nil {
190			for i, f := range visible {
191				if sameFinding(*prev, f) {
192					return i
193				}
194			}
195		}
196		return clampIndex(prevCursor, len(visible))
197	}
198	
199	// cveGroupColumns describes the grouped list of the CVE tab: Severity, Package,
200	// Change, CVEs, Fix. Cells are plain text (Rule 122); only Severity is coloured,
201	// and it is also its word.
202	func cveGroupColumns() []datatable.Column[fixGroup] {
203		return []datatable.Column[fixGroup]{
204			{
205				Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
206				Cell:  func(g fixGroup) string { return string(g.Severity) },
207				Style: func(g fixGroup) lipgloss.Style { return theme.SeverityTextStyle(string(g.Severity)) },
208				Less:  func(a, b fixGroup) bool { return severityRank(a.Severity) < severityRank(b.Severity) },
209			},
210			{
211				Title: "Package", Sizing: datatable.SizingContent, MinWidth: 14,
212				Cell: func(g fixGroup) string { return g.Subject },
213				Less: func(a, b fixGroup) bool { return a.Subject < b.Subject },
214			},
215			{
216				Title: "Change", Sizing: datatable.SizingContent, MinWidth: 16, Flex: 1,
217				Cell: func(g fixGroup) string { return g.Change },
218				Less: func(a, b fixGroup) bool { return a.Change < b.Change },
219			},
220			{
221				Title: "CVEs", Sizing: datatable.SizingFixed, MinWidth: 5, DescFirst: true,
222				Cell: func(g fixGroup) string { return strconv.Itoa(len(g.Members)) },
223				Less: func(a, b fixGroup) bool { return len(a.Members) < len(b.Members) },
224			},
225			{
226				Title: "Fix", Sizing: datatable.SizingContent, MinWidth: 16, MaxWidth: 24, Optional: true,
227				Cell: func(g fixGroup) string { return g.Status.Label() },
228				Less: func(a, b fixGroup) bool { return a.Status.Label() < b.Status.Label() },
229			},
230		}
231	}
