// ordered. A lone version is returned as is, orderable or not.
func highest(versions []string) string {
	best := versions[0]
	for _, v := range versions[1:] {
		c, ok := scan.CompareVersions(v, best)
		if !ok {
			return ""
		}
		if c > 0 {
			best = v
		}
	}
	return best
}

